package escuela.personal.dto;
public record EmpleadoVista(Long id,Long institucionId,String codigo,String nombres,String primerApellido,String segundoApellido,String email,String telefono,boolean activo,boolean foto,Long version,Long maestroId,boolean docenteActivo,String codigoDocente,String usuarioDocente,ResumenLaboral resumenLaboral){
 public EmpleadoVista(Long id,Long institucionId,String codigo,String nombres,String primerApellido,String segundoApellido,String email,String telefono,boolean activo,boolean foto,Long version,Long maestroId,boolean docenteActivo,String codigoDocente,String usuarioDocente){this(id,institucionId,codigo,nombres,primerApellido,segundoApellido,email,telefono,activo,foto,version,maestroId,docenteActivo,codigoDocente,usuarioDocente,null);}
 public EmpleadoVista conResumenLaboral(ResumenLaboral resumen){return new EmpleadoVista(id,institucionId,codigo,nombres,primerApellido,segundoApellido,email,telefono,activo,foto,version,maestroId,docenteActivo,codigoDocente,usuarioDocente,resumen);}
 public String nombre(){return java.util.stream.Stream.of(nombres,primerApellido,segundoApellido).filter(x->x!=null&&!x.isBlank()).collect(java.util.stream.Collectors.joining(" "));}
 public EmpleadoForm formulario(){var f=new EmpleadoForm();f.setInstitucionId(institucionId);f.setCodigo(codigo);f.setNombres(nombres);f.setPrimerApellido(primerApellido);f.setSegundoApellido(segundoApellido);f.setEmail(email);f.setTelefono(telefono);f.setVersion(version);return f;}
}
